
let tarefas = JSON.parse(
    localStorage.getItem("tarefas")
    ) || [];

    let codigoAtual = Number(
        localStorage.getItem("codigoAtual")
        ) || 1;

        // Salvar tarefas no navegador
        function salvarTarefas() {
            localStorage.setItem(
                    "tarefas",
                            JSON.stringify(tarefas)
                                );

                                    localStorage.setItem(
                                            "codigoAtual",
                                                    codigoAtual
                                                        );
                                                        }

                                                        // Validar os dados
                                                        function validarTarefa(titulo, descricao) {
                                                            if (titulo.trim() === "") {
                                                                    alert("Digite o título da tarefa!");
                                                                            return false;
                                                                                }

                                                                                    if (descricao.trim() === "") {
                                                                                            alert("Digite a descrição da tarefa!");
                                                                                                    return false;
                                                                                                        }

                                                                                                            return true;
                                                                                                            }

                                                                                                            // Cadastrar uma tarefa
                                                                                                            function cadastrarTarefa(titulo, descricao, prioridade) {
                                                                                                                if (!validarTarefa(titulo, descricao)) {
                                                                                                                        return;
                                                                                                                            }

                                                                                                                                const tarefa = {
                                                                                                                                        codigo: codigoAtual,
                                                                                                                                                titulo: titulo,
                                                                                                                                                        descricao: descricao,
                                                                                                                                                                prioridade: prioridade,
                                                                                                                                                                        concluida: false
                                                                                                                                                                            };

                                                                                                                                                                                tarefas.push(tarefa);

                                                                                                                                                                                    codigoAtual++;

                                                                                                                                                                                        salvarTarefas();
                                                                                                                                                                                            listarTarefas();

                                                                                                                                                                                                document.getElementById("formTarefa").reset();
                                                                                                                                                                                                }

                                                                                                                                                                                                // Listar tarefas
                                                                                                                                                                                                function listarTarefas(lista = tarefas) {
                                                                                                                                                                                                    const container = document.getElementById("listaTarefas");

                                                                                                                                                                                                        container.innerHTML = "";

                                                                                                                                                                                                            if (lista.length === 0) {
                                                                                                                                                                                                                    container.innerHTML = "<p>Nenhuma tarefa encontrada.</p>";
                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                    lista.forEach(function(tarefa) {
                                                                                                                                                                                                                                            const elemento = document.createElement("div");

                                                                                                                                                                                                                                                    elemento.className = "tarefa";

                                                                                                                                                                                                                                                            if (tarefa.concluida) {
                                                                                                                                                                                                                                                                        elemento.classList.add("concluida");
                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                        elemento.classList.add(
                                                                                                                                                                                                                                                                                                    tarefa.prioridade.toLowerCase()
                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                    elemento.innerHTML = `
                                                                                                                                                                                                                                                                                                                                <h3>${tarefa.titulo}</h3>

                                                                                                                                                                                                                                                                                                                                            <p><strong>Código:</strong> ${tarefa.codigo}</p>

                                                                                                                                                                                                                                                                                                                                                        <p>${tarefa.descricao}</p>

                                                                                                                                                                                                                                                                                                                                                                    <p><strong>Prioridade:</strong>
                                                                                                                                                                                                                                                                                                                                                                                ${tarefa.prioridade}</p>

                                                                                                                                                                                                                                                                                                                                                                                            <p><strong>Status:</strong>
                                                                                                                                                                                                                                                                                                                                                                                                        ${tarefa.concluida ? "Concluída" : "Pendente"}</p>

                                                                                                                                                                                                                                                                                                                                                                                                                    <div class="acoes">
                                                                                                                                                                                                                                                                                                                                                                                                                                    <button class="concluir"
                                                                                                                                                                                                                                                                                                                                                                                                                                                        onclick="concluirTarefa(${tarefa.codigo})">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ${tarefa.concluida ? "Reabrir" : "Concluir"}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </button>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button onclick="alterarPrioridade(${tarefa.codigo})">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Alterar prioridade
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </button>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <button class="excluir"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onclick="excluirTarefa(${tarefa.codigo})">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Excluir
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            `;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    container.appendChild(elemento);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Buscar tarefa usando find()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function buscarTarefa(titulo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return tarefas.find(function(tarefa) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return tarefa.titulo.toLowerCase()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .includes(titulo.toLowerCase());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Concluir uma tarefa
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function concluirTarefa(codigo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const tarefa = tarefas.find(function(item) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return item.codigo === codigo;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (tarefa) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                tarefa.concluida = !tarefa.concluida;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        salvarTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                listarTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Alterar prioridade
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function alterarPrioridade(codigo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const tarefa = tarefas.find(function(item) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return item.codigo === codigo;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (tarefa) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const prioridades = ["Baixa", "Média", "Alta"];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let atual = prioridades.indexOf(tarefa.prioridade);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                tarefa.prioridade =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            prioridades[(atual + 1) % prioridades.length];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    salvarTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            listarTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Excluir tarefa
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function excluirTarefa(codigo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    tarefas = tarefas.filter(function(tarefa) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return tarefa.codigo !== codigo;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    salvarTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        listarTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Evento do formulário
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("formTarefa")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .addEventListener("submit", function(event) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    event.preventDefault();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const titulo = document.getElementById("titulo").value;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const descricao = document.getElementById("descricao").value;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const prioridade = document.getElementById("prioridade").value;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cadastrarTarefa(titulo, descricao, prioridade);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Evento de busca
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("busca")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .addEventListener("input", function() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const texto = this.value.toLowerCase();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const resultado = tarefas.filter(function(tarefa) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return tarefa.titulo.toLowerCase()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .includes(texto);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        listarTarefas(resultado);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Mostrar tarefas ao abrir o site
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            listarTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            